from lib10 import *
S='science'
def B(ch,cn,t,tn,*a,**k): build(S,ch,t,tn,*a,cname=cn,tname=tn,**k)
A="Both A and R are true and R explains A"
C,CN='life-processes','Life Processes'
B(C,CN,'nutrition','Nutrition in plants and human beings',
 "Where does the energy come from?",
 "A plant sits in the sun and makes its own food, while we must eat. Both kinds of living things need nutrition to stay alive.",
 [("Life processes are the basic functions that keep an organism alive: nutrition, respiration, transport and excretion.","life processes"),
  ("Autotrophs make their own food by photosynthesis: 6CO2 + 6H2O in sunlight and chlorophyll gives glucose + 6O2.","photosynthesis"),
  ("Photosynthesis needs chlorophyll, sunlight, carbon dioxide and water. Stomata let in CO2 and release oxygen.","stomata"),
  ("Heterotrophs depend on others for food. Examples are holozoic nutrition in humans, saprophytic nutrition in fungi and parasitic nutrition in cuscuta.","heterotrophs"),
  ("In humans, digestion starts in the mouth where salivary amylase breaks starch into sugar. The food travels through the oesophagus to the stomach.","mouth and oesophagus"),
  ("The stomach secretes hydrochloric acid, which kills bacteria and activates pepsin, and mucus protects the stomach wall.","stomach"),
  ("In the small intestine bile from the liver emulsifies fats and pancreatic juice has trypsin, lipase and amylase. Villi absorb digested food.","small intestine"),
  ("The large intestine absorbs water, and undigested food leaves the body through the anus.","large intestine")],
 ("Why is bile secreted although it contains no enzymes?",[("Bile contains salts that make the medium alkaline for enzymes of the pancreas.","Pancreatic enzymes need alkaline conditions."),("It also breaks large fat globules into smaller ones, which is emulsification.","More surface for lipase."),("So fat digestion becomes faster.","Final effect.")]),
 ("What is the path and chemistry of nutrition?",["Photosynthesis in plants","Digestive tract in humans","Enzymes and their action"],["Thinking digestion ends in the stomach"]),
 ["Autotrophs photosynthesise; heterotrophs depend on others.","Digestive enzymes: amylase, pepsin, trypsin, lipase.","Villi in the small intestine increase surface area for absorption."],
 [mcq("r1-nu1",1,"Raw materials for photosynthesis","CO2, water and sunlight",[("O2 and water","Oxygen is released."),("glucose and O2","They are products.")],"Chlorophyll absorbs light."),
  tf("r1-nu2",1,"Stomata release oxygen during photosynthesis.",True,"Gas exchange."),
  mcq("r2-nu3",2,"The enzyme in saliva","salivary amylase",[("pepsin","In the stomach."),("lipase","In pancreatic juice.")],"Breaks starch."),
  mcq("r2-nu4",2,"Assertion (A): Villi increase absorption. Reason (R): They have a large surface area and rich blood supply.",A,[("A true, R false","R explains A."),("A false, R true","Villi help absorption.")],"Villi."),
  short("r2-nu5",2,"Name the acid in the stomach",["hydrochloric acid","hcl"],"HCl.",[("sulphuric acid","Not secreted.")]),
  mcq("r3-nu6",3,"Fats are emulsified by","bile",[("saliva","Saliva has amylase."),("pepsin","Pepsin digests proteins.")],"Bile salts."),
  tf("r3-nu7",3,"Digestion of proteins begins in the stomach.",True,"Pepsin."),
  mcq("r3-nu8",3,"Cuscuta shows","parasitic nutrition",[("saprophytic nutrition","It takes food from a host."),("autotrophic nutrition","It is a parasite.")],"Takes nutrients from the host plant.")])
B(C,CN,'respiration-transport-excretion','Respiration, transportation and excretion',
 "Breathing, pumping and filtering",
 "Every cell needs oxygen, a blood supply and a way to remove waste. Respiration, transport and excretion handle these jobs.",
 [("Respiration breaks down glucose to release energy stored as ATP. Aerobic respiration uses oxygen: glucose gives CO2 + water + energy.","respiration"),
  ("Anaerobic respiration happens without oxygen: in yeast it gives ethanol and CO2, and in our muscles it gives lactic acid, which causes cramps.","anaerobic"),
  ("In humans air passes through the nose, pharynx, larynx, trachea and bronchi to alveoli, where gas exchange happens. Haemoglobin carries oxygen.","alveoli"),
  ("The human heart has four chambers and gives double circulation. Oxygenated and deoxygenated blood do not mix.","four-chambered heart"),
  ("Arteries carry blood away from the heart; veins carry blood to it. Capillaries exchange materials with tissues.","arteries and veins"),
  ("In plants, xylem carries water and minerals upward using transpiration pull, and phloem carries food in both directions, called translocation.","xylem and phloem"),
  ("Excretion removes nitrogenous wastes. In humans the kidneys filter blood in nephrons, forming urine that passes through the ureter to the bladder.","nephron"),
  ("In kidney failure, haemodialysis acts as an artificial kidney. Plants excrete through leaves, resins and gums.","dialysis")],
 ("Why do athletes get muscle cramps after heavy exercise?",[("In heavy exercise oxygen supply is low, so pyruvate is converted anaerobically.","Anaerobic respiration."),("Lactic acid builds up in the muscles.","Product."),("That accumulation causes cramps.","The effect.")]),
 ("How do respiration, transport and excretion work?",["Aerobic and anaerobic","Double circulation","Nephron filters blood"],["Mixing arteries and veins"]),
 ["Aerobic respiration gives much more energy than anaerobic.","The heart has four chambers and double circulation.","Kidneys filter blood; nephron is the unit."],
 [mcq("r1-rt1",1,"Gas exchange in lungs happens in","alveoli",[("trachea","Only a passage."),("bronchi","Only a passage.")],"Thin walls."),
  tf("r1-rt2",1,"Arteries carry blood away from the heart.",True,"Definition."),
  mcq("r2-rt3",2,"The unit of the kidney","nephron",[("neuron","Unit of the nervous system."),("alveolus","Unit of lungs.")],"Filters blood."),
  mcq("r2-rt4",2,"Assertion (A): Four-chambered heart gives efficient oxygen supply. Reason (R): Oxygenated and deoxygenated blood do not mix.",A,[("A true, R false","R is why."),("A false, R true","Hence efficient.")],"Double circulation."),
  short("r2-rt5",2,"Acid formed in muscles in anaerobic respiration",["lactic acid"],"Lactic acid.",[("acetic acid","Not formed.")]),
  mcq("r3-rt6",3,"Phloem transports","food (sucrose)",[("water only","That is xylem."),("oxygen","Not transported by phloem.")],"Translocation."),
  tf("r3-rt7",3,"Yeast produces ethanol in anaerobic respiration.",True,"Fermentation."),
  mcq("r3-rt8",3,"Blood from the lungs enters the heart in the","left atrium",[("right atrium","Gets deoxygenated blood."),("right ventricle","Sends blood to lungs.")],"Pulmonary veins.")])
C,CN='control-and-coordination','Control and Coordination'
B(C,CN,'nervous-system','Nervous system and reflex action',
 "Touching a hot pan",
 "You pull your hand away from a hot pan before you even feel the pain. The nervous system makes that happen.",
 [("The nervous system picks up information from the environment through receptors, passes it as electrical impulses and triggers a response.","receptors and effectors"),
  ("A neuron has dendrites that receive signals, a cell body and an axon that carries the impulse to the next neuron across a synapse.","neuron"),
  ("A reflex action is a quick automatic response, like withdrawing the hand from a flame. It follows a reflex arc: receptor, sensory neuron, spinal cord, motor neuron, effector.","reflex arc"),
  ("The reflex is processed in the spinal cord, not in the brain, which saves time.","spinal cord"),
  ("The brain has the forebrain (cerebrum) for thinking and memory, the midbrain, and the hindbrain with the cerebellum for balance and the medulla for involuntary actions.","brain parts"),
  ("The brain is protected by the skull and by cerebrospinal fluid in the meninges.","protection"),
  ("In plants, tropic movements respond to stimuli: phototropism to light, geotropism to gravity, hydrotropism to water and chemotropism toward chemicals.","tropisms"),
  ("Nastic movements like the touch-me-not's folding leaves are quick and not directed by the stimulus.","nastic")],
 ("Trace the path when your hand touches a hot object.",[("The heat receptor in the skin sends an impulse along the sensory neuron.","Receptor."),("The spinal cord relays it directly to a motor neuron.","Reflex arc."),("The muscle (effector) contracts and the hand moves away.","Response.")]),
 ("What is a reflex arc and what parts form the brain?",["Receptor to effector path","Spinal cord","Forebrain, midbrain, hindbrain"],["Thinking all reflexes involve the brain"]),
 ["Neurons carry electrical impulses; a synapse is the gap between neurons.","Reflex arc: receptor, sensory neuron, spinal cord, motor neuron, effector.","Plants respond by tropic movements."],
 [mcq("r1-ns1",1,"The part of the neuron that receives signals","dendrite",[("axon","Carries away the signal."),("synapse","The gap.")],"Dendrite."),
  tf("r1-ns2",1,"A reflex action is processed in the spinal cord.",True,"It is fast."),
  mcq("r2-ns3",2,"The part of the brain controlling balance","cerebellum",[("cerebrum","Thinking."),("medulla","Involuntary actions.")],"Hindbrain."),
  mcq("r2-ns4",2,"Assertion (A): A roots bend toward gravity. Reason (R): Roots show positive geotropism.",A,[("A true, R false","R names the response."),("A false, R true","Roots grow downward.")],"Geotropism."),
  short("r2-ns5",2,"Gap between two neurons",["synapse"],"Synapse.",[("axon","Axon is a part of a neuron.")]),
  mcq("r3-ns6",3,"Sensory neurons carry impulses","from receptors to the CNS",[("from CNS to muscle","That is motor neurons."),("only within the brain","They connect receptors to the CNS.")],"Afferent."),
  tf("r3-ns7",3,"Touch-me-not's quick folding is a nastic movement.",True,"Not directed by the stimulus."),
  mcq("r3-ns8",3,"The brain is protected by","skull and meninges with fluid",[("ribs","They protect the lungs."),("skin","Not enough.")],"Cerebrospinal fluid.")])
B(C,CN,'hormones','Hormones in animals and plants',
 "Chemical messengers",
 "Why does your heart race when you are scared? Hormones, the chemical messengers of the body, take the message.",
 [("Hormones are chemical messengers made by endocrine glands and carried in blood to target organs.","hormones"),
  ("Adrenaline from the adrenal gland prepares the body for fight or flight by raising heartbeat and blood to muscles.","adrenaline"),
  ("Thyroxine from the thyroid regulates metabolism. It needs iodine; lack of iodine causes goitre.","thyroxine"),
  ("Insulin from the pancreas lowers blood sugar. Lack of insulin causes diabetes.","insulin"),
  ("Growth hormone from the pituitary controls growth; too little gives dwarfism and too much gives gigantism.","growth hormone"),
  ("Testosterone in males and oestrogen in females control puberty changes.","sex hormones"),
  ("Hormones act by feedback: when blood sugar rises, insulin is secreted, and when it falls, secretion is reduced.","feedback"),
  ("Plant hormones: auxin (growth in the shoot tip), gibberellins (stem growth), cytokinins (cell division), abscisic acid (inhibits growth, wilting) and ethylene (fruit ripening).","plant hormones")],
 ("Why should we use iodised salt?",[("Iodine is required to make thyroxine.","Thyroid hormone."),("Lack of iodine causes goitre, a swollen neck.","Deficiency disease."),("Iodised salt prevents it.","Daily source.")]),
 ("Name key hormones and their functions.",["Adrenaline, thyroxine, insulin","Growth hormone and sex hormones","Plant hormones"],["Thinking hormones act through nerves"]),
 ["Hormones are chemical messengers released into blood.","Insulin lowers blood sugar; thyroxine regulates metabolism (needs iodine).","Plant hormones: auxin, gibberellin, cytokinin, abscisic acid, ethylene."],
 [mcq("r1-ho1",1,"The hormone that lowers blood sugar","insulin",[("adrenaline","Raises heartbeat."),("thyroxine","Regulates metabolism.")],"Pancreas."),
  tf("r1-ho2",1,"Hormones are carried by blood.",True,"They reach target organs."),
  mcq("r2-ho3",2,"Goitre is caused by lack of","iodine",[("iron","Causes anaemia."),("calcium","Causes weak bones.")],"Thyroxine."),
  mcq("r2-ho4",2,"Assertion (A): Fruit ripening is helped by ethylene. Reason (R): Ethylene is a plant hormone.",A,[("A true, R false","R is true."),("A false, R true","Ethylene ripens fruits.")],"Gas hormone."),
  short("r2-ho5",2,"Hormone that promotes cell division in plants",["cytokinin","cytokinins"],"Cytokinin.",[("auxin","Auxin helps cell elongation.")]),
  mcq("r3-ho6",3,"The 'fight or flight' hormone","adrenaline",[("insulin","No."),("oestrogen","No.")],"Adrenal gland."),
  tf("r3-ho7",3,"Abscisic acid inhibits growth.",True,"It causes wilting."),
  mcq("r3-ho8",3,"Diabetes is associated with","insulin deficiency",[("thyroxine deficiency","Causes hypothyroidism."),("growth hormone","Causes dwarfism.")],"Pancreas.")])
C,CN='how-do-organisms-reproduce','How do Organisms Reproduce?'
B(C,CN,'asexual-reproduction','Asexual reproduction and variation',
 "One parent, many offspring",
 "A bit of Hydra grows into a new animal and a potato eye becomes a new plant. Many organisms reproduce from a single parent.",
 [("Reproduction creates new individuals that copy the DNA of the parent, with small variations that help species survive.","DNA copying"),
  ("Binary fission: Amoeba splits into two, and Plasmodium splits into many in multiple fission.","fission"),
  ("Fragmentation: Spirogyra breaks into pieces and each grows into a new filament.","fragmentation"),
  ("Regeneration: Hydra and Planaria regrow lost parts from specialised cells.","regeneration"),
  ("Budding: Hydra forms a bud that grows and detaches.","budding"),
  ("Vegetative propagation: new plants from roots, stems or leaves, as in potato, Bryophyllum and sugarcane. Grafting, cutting and layering help gardeners.","vegetative propagation"),
  ("Spore formation: Rhizopus makes spores in sporangia that grow in damp conditions.","spores"),
  ("Asexual reproduction gives little variation, but it is fast and needs only one parent. Tissue culture grows plants from a few cells in a lab.","tissue culture")],
 ("Explain why asexual reproduction gives little variation.",[("Only one parent is involved.","One set of DNA."),("DNA is copied with minor errors.","Small variations."),("So offspring are nearly identical.","Clones.")]),
 ("Name types of asexual reproduction with examples.",["Fission, fragmentation, regeneration","Budding, vegetative, spore","Little variation"],["Thinking all reproduction needs two parents"]),
 ["Asexual reproduction needs one parent and gives clones.","Types: fission, fragmentation, regeneration, budding, vegetative propagation, spore formation.","Variation helps species survive."],
 [mcq("r1-ar1",1,"Amoeba reproduces by","binary fission",[("budding","Hydra."),("spores","Rhizopus.")],"Splits into two."),
  tf("r1-ar2",1,"Hydra can reproduce by budding.",True,"Bud grows into a new Hydra."),
  mcq("r2-ar3",2,"Bryophyllum reproduces vegetatively from its","leaves",[("roots","No."),("seeds","No.")],"Leaf notches."),
  mcq("r2-ar4",2,"Assertion (A): Asexual reproduction produces nearly identical offspring. Reason (R): Only one parent is involved.",A,[("A true, R false","R is correct."),("A false, R true","Hence little variation.")],"Clones."),
  short("r2-ar5",2,"Fungus that reproduces by spores",["rhizopus"],"Bread mould.",[("amoeba","Amoeba divides by fission.")]),
  mcq("r3-ar6",3,"Planaria regrows lost parts by","regeneration",[("budding","No."),("fission","No.")],"Specialised cells."),
  tf("r3-ar7",3,"Variation is useful for species survival.",True,"It helps in changing environments."),
  mcq("r3-ar8",3,"Spirogyra uses","fragmentation",[("budding","No."),("spores only","No.")],"Filament breaks.")])
B(C,CN,'sexual-reproduction','Sexual reproduction in plants and humans',
 "From flower to fruit, from cell to baby",
 "A flower, a fruit and a baby all come from fertilisation, the joining of two cells. Sexual reproduction mixes DNA from two parents.",
 [("Sexual reproduction involves two parents and gametes, which fuse to form a zygote. DNA mixing produces variation.","gametes and zygote"),
  ("A flower has sepals, petals, stamens (male: anther and filament) and pistil (female: stigma, style and ovary).","parts of a flower"),
  ("Pollination moves pollen from anther to stigma by wind, water or insects. Self-pollination is within one flower; cross-pollination is between flowers.","pollination"),
  ("Fertilisation: a pollen tube carries male gametes to the ovule. The zygote becomes an embryo, the ovule becomes a seed and the ovary becomes a fruit.","fertilisation"),
  ("Human male: testes make sperm and testosterone, the vas deferens carries sperm, and glands add fluid to make semen.","male system"),
  ("Human female: ovaries release an egg, the fallopian tube is the site of fertilisation, and the uterus holds the embryo; the placenta gives nourishment.","female system"),
  ("If the egg is not fertilised, the uterine lining breaks down in menstruation every month.","menstruation"),
  ("Reproductive health: contraceptive methods prevent pregnancy; barrier methods like condoms also reduce sexually transmitted infections. Sex ratio matters, and sex-selective abortion is illegal.","reproductive health")],
 ("Describe the changes in a flower after fertilisation.",[("The zygote develops into an embryo inside the ovule.","Zygote."),("The ovule becomes the seed.","Seed."),("The ovary becomes the fruit, and petals and sepals wither.","Fruit.")]),
 ("How does sexual reproduction occur in flowers and humans?",["Pollination and fertilisation","Male and female systems","Reproductive health"],["Mixing pollination and fertilisation"]),
 ["Pollination moves pollen to the stigma; fertilisation joins the gametes.","Ovule becomes seed, ovary becomes fruit.","In humans, fertilisation occurs in the fallopian tube; the embryo implants in the uterus."],
 [mcq("r1-sr1",1,"The male part of a flower","stamen",[("pistil","Female."),("sepal","Protective.")],"Anther holds pollen."),
  tf("r1-sr2",1,"Fertilisation in humans occurs in the fallopian tube.",True,"Sperm meets the egg."),
  mcq("r2-sr3",2,"After fertilisation the ovary becomes the","fruit",[("seed","That is the ovule."),("flower","No.")],"Fruit."),
  mcq("r2-sr4",2,"Assertion (A): Placenta nourishes the embryo. Reason (R): It brings blood from mother and embryo close together.",A,[("A true, R false","R is correct."),("A false, R true","Hence nourishment.")],"Exchange."),
  short("r2-sr5",2,"Transfer of pollen from anther to stigma is",["pollination"],"Pollination.",[("fertilisation","That is gamete fusion.")]),
  mcq("r3-sr6",3,"The testes produce","sperm and testosterone",[("eggs","Ovaries make eggs."),("urine","Kidneys.")],"Male gonads."),
  tf("r3-sr7",3,"Menstruation occurs when the egg is not fertilised.",True,"The lining breaks down."),
  mcq("r3-sr8",3,"Condoms help prevent","pregnancy and some infections",[("only pregnancy","They also reduce infections."),("anaemia","No.")],"Barrier method.")])
C,CN='heredity','Heredity'
B(C,CN,'mendels-experiments','Heredity, Mendel and sex determination',
 "Why do children look like parents?",
 "A child may have the mother's nose and the father's eyes. Heredity explains how traits pass from parents to children.",
 [("Heredity is the transmission of traits from parents to offspring. Variation is differences among individuals.","heredity and variation"),
  ("Gregor Mendel worked on garden pea plants and studied traits like tall and short, round and wrinkled seeds.","Mendel"),
  ("When he crossed a pure tall plant with a pure short plant, all F1 plants were tall. In F2 tall and short appeared in the ratio 3 : 1.","3 : 1 ratio"),
  ("So the tall trait is dominant and the short trait is recessive. Each trait is controlled by a pair of factors, now called genes.","dominant and recessive"),
  ("A dihybrid cross of round yellow and wrinkled green seeds gave a 9 : 3 : 3 : 1 ratio in F2, showing independent inheritance of traits.","9 : 3 : 3 : 1"),
  ("Traits are expressed through proteins made from genes on DNA in chromosomes.","genes and proteins"),
  ("Sex determination in humans: 22 pairs of autosomes and one pair of sex chromosomes. Females are XX and males are XY.","XX and XY"),
  ("A child's sex depends on the father's sperm: X gives a girl and Y a boy. The chance of a boy or girl is 50 percent each.","sex determination")],
 ("In a pea cross Tt x Tt, find the ratio of tall to short plants.",[("Gametes of each parent: T and t.","Each carries one gene."),("Offspring: TT, Tt, Tt, tt.","Punnett square."),("Three tall (TT, Tt, Tt) and one short (tt): ratio 3 : 1.","Dominant T.")]),
 ("How are traits inherited?",["Mendel's 3:1","Dominant and recessive","XX and XY"],["Thinking the mother decides the sex"]),
 ["Monohybrid cross F2 ratio 3 : 1; dihybrid ratio 9 : 3 : 3 : 1.","Genes are on DNA in chromosomes.","Males XY, females XX; the father's sperm decides the sex."],
 [mcq("r1-me1",1,"Mendel used","garden pea plants",[("fruit flies","Used later by others."),("mice","No.")],"Pisum sativum."),
  tf("r1-me2",1,"In F1 of a tall x short cross all plants were tall.",True,"Tall is dominant."),
  mcq("r2-me3",2,"F2 ratio in a monohybrid cross","3 : 1",[("1 : 1","Test cross."),("9 : 3 : 3 : 1","Dihybrid.")],"Tall to short."),
  mcq("r2-me4",2,"Assertion (A): A child's sex depends on the father. Reason (R): Sperm carries X or Y, egg always carries X.",A,[("A true, R false","R is correct."),("A false, R true","Father decides.")],"X or Y."),
  short("r2-me5",2,"Human female sex chromosomes",["xx"],"XX.",[("xy","That is male.")]),
  mcq("r3-me6",3,"Genes are found on","chromosomes",[("ribosomes","No."),("mitochondria only","Mostly chromosomes.")],"DNA."),
  tf("r3-me7",3,"A recessive trait is expressed when two copies of the recessive gene are present.",True,"tt."),
  num("r3-me8",3,"In 9:3:3:1, the number of plants with both recessive traits out of 16",1,"Only 1/16.",[(3,"3 are single-trait recessive.")])])
